import{_ as a,g as r,e as t,a4 as c}from"./chunks/framework.CEYJDsBW.js";const s=JSON.parse('{"title":"dev.anvilcraft.resource.ageratum","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/26.1/api/dev-anvilcraft-resource-ageratum.md","filePath":"ageratum/26.1/api/dev-anvilcraft-resource-ageratum.md"}'),d={name:"ageratum/26.1/api/dev-anvilcraft-resource-ageratum.md"};function o(i,e,u,n,m,b){return r(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="dev-anvilcraft-resource-ageratum" tabindex="-1">dev.anvilcraft.resource.ageratum <a class="header-anchor" href="#dev-anvilcraft-resource-ageratum" aria-label="Permalink to &quot;dev.anvilcraft.resource.ageratum&quot;">​</a></h1><h2 id="ageratum" tabindex="-1">Ageratum <a class="header-anchor" href="#ageratum" aria-label="Permalink to &quot;Ageratum&quot;">​</a></h2><p>相关用法 · <a href="../guides/open.html">从服务端打开页面</a></p><p><code>public class Ageratum</code></p><p><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L21" target="_blank" rel="noreferrer">类型声明</a></p><p>Ageratum 模组主类。 该模组定位为“游戏内手册框架”，用于为其它模组提供统一的文档展示能力。 当前负责模组初始化与文档打开入口。</p><p>类型注解 <code>@Mod(Ageratum.MOD_ID)</code></p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final String MOD_ID</code></td><td>模组 ID，也是默认命名空间。<br>初值 <code>&quot;ageratum&quot;</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L26" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final Registrum REGISTRUM</code></td><td>初值 <code>Registrum.create(Ageratum.MOD_ID)</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L27" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public Ageratum(IEventBus modEventBus, ModContainer modContainer)</code></td><td>模组构造函数，由 NeoForge 在加载时调用。<br>参数 <code>modEventBus</code> 模组专属事件总线<br>参数 <code>modContainer</code> 模组容器<br>实现调用 <code>AgeratumDataComponents.register()</code><br>实现调用 <code>AgeratumItems.register()</code><br>实现调用 <code>AgeratumItemGroups.TABS.register(modEventBus)</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L35" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>public static Identifier location(String path)</code></td><td>生成以本模组 ID 为命名空间的 Identifier。<br>参数 <code>path</code> 资源路径（不含命名空间前缀）<br>返回 完整的资源位置<br>末尾返回 <code>Identifier.fromNamespaceAndPath(Ageratum.MOD_ID, path)</code><br><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/AgeratumClient.java#L91" target="_blank" rel="noreferrer">调用处 AgeratumClient.onReloadListenerRegister</a></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L48" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static void openGuide(ServerPlayer player, Identifier location)</code></td><td>打开指定资源位置的文档。 客户端调用：直接尝试打开文档界面。 服务端调用：通过网络包通知客户端打开文档。 若文档不存在则忽略，不抛出异常。<br>执行 <code>AgeratumNetwork.sendOpenGuide(player, location)</code><br><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/item/GuideBookItem.java#L30" target="_blank" rel="noreferrer">调用处 GuideBookItem.use</a></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L59" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static void openGitHubGuide(ServerPlayer player, String uri)</code></td><td>打开 GitHub 远程指南。 服务端调用：将原始 URI 字符串转发给客户端，由客户端执行下载与展示。<br>参数 <code>player</code> 目标玩家<br>参数 <code>uri</code> GitHub 指南 URI（如 github:user/repo#path:assets/xxx&amp;commit=sha）<br>执行 <code>AgeratumNetwork.sendGitHubOpenGuide(player, uri)</code><br><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/item/GuideBookItem.java#L28" target="_blank" rel="noreferrer">调用处 GuideBookItem.use</a></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L71" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table>',8)])])}const g=a(d,[["render",o]]);export{s as __pageData,g as default};
